import os, numpy as np
runs = {}
for i in range(1, 50):
    if os.path.exists(f'/work/fwd/r{i}/run.npz'):
        runs[i] = np.load(f'/work/fwd/r{i}/run.npz')
print("Runs:", sorted(runs.keys()))
r1 = runs[1]
# L0H0 pattern
p = r1['L0H0_ATTN_pattern'][0]
print("\nL0H0 tops:", [int(np.argmax(p[i])) for i in range(10)])
print("L0H0 maxw:", [round(float(p[i,int(np.argmax(p[i]))]),3) for i in range(10)])
# L2H0 pattern
p2 = r1['L2H0_ATTN_pattern'][0]
print("L2H0 tops:", [int(np.argmax(p2[i])) for i in range(10)])
print("L2H0 maxw:", [round(float(p2[i,int(np.argmax(p2[i]))]),3) for i in range(10)])
# Find ablation runs
for rid, d in sorted(runs.items()):
    if rid==1: continue
    n=d['logits'].shape[0]
    l0h0_zero = float(np.abs(d['L0H0_ATTN']).max())<0.01
    l0mlp_zero = float(np.abs(d['L0_MLP']).max())<0.01
    if l0h0_zero or l0mlp_zero:
        what = []
        if l0h0_zero: what.append('L0H0')
        if l0mlp_zero: what.append('L0MLP')
        for bid,bd in sorted(runs.items()):
            if bd['logits'].shape[0]==n and bid<rid:
                print(f"\nr{bid}vs r{rid} ({'+'.join(what)} ablated, n={n}):")
                for c in ['L0_MLP','L1_MLP']:
                    dd=[np.linalg.norm(bd[c][i,p]-d[c][i,p]) for i in range(n) for p in range(10)]
                    print(f"  {c}: max={max(dd):.4f}, mean={np.mean(dd):.4f}")
                break

